                _ => result.push(' '),
            }
        }
        result.push(' ');
    }
    result.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn organisation_core(name: &str) -> String {
    const SUFFIXES: &[&[&str]] = &[
        &["public", "limited", "company"], &["community", "interest", "company"],
        &["limited", "liability", "partnership"], &["limited", "partnership"],
        &["limited"], &["ltd"], &["plc"], &["llp"], &["lp"], &["cic"],
    ];
