        words.truncate(words.len() - suffix.len());
    }
    words.join(" ")
}

fn person_core(name: &str) -> String {
    const TITLES: &[&str] = &[
        "mr", "mrs", "ms", "miss", "mx", "dr", "prof", "professor", "sir", "dame",
