    values = {field['name']: field.get('value') for field in fields}
    donor = values.get('DonorName')
    if donor is None and grouped:
        donor = values.get('Name')
    roles = [('donor', donor), ('payer', values.get('PayerName')), ('ultimate_payer', values.get('UltimatePayerName'))]
    for role, name in roles:
        kind = values.get('DonorStatus') if role == 'donor' else None
        number = values.get('DonorCompanyIdentifier') if role == 'donor' else None
        if any(value is not None for value in (name, kind, number)):
            expected_funders[(*prefix, scope, ordinal, role)] = (name, kind, number, pointer)

def funding_groups(fields, pointer):
    if any(field['name'] in ('Value', 'PaymentType') for field in fields):
        yield fields, pointer, False
    for index, field in enumerate(fields):
        for nested_index, nested in enumerate(field.get('values') or []):
            nested_pointer = f'{pointer}/{index}/values/{nested_index}'
            if field['name'] == 'Donors':
                yield nested, nested_pointer, True
            else:
                yield from funding_groups(nested, nested_pointer)

for (member, declaration_id), source in sources.items():
    version_index, version = max(enumerate(source['versions']), key=lambda item: (item[1]['register']['publishedDate'], item[1]['register']['id'], item[0]))
    prefix = (member, declaration_id, version['register']['id'])
    fields = version.get('fields') or []
    pointer = f'/versions/{version_index}/fields'
    if not any(field['name'] in ('Value', 'PaymentType') for field in fields):
        add_mentions(prefix, fields, 'declaration', None, pointer)
    for ordinal, (group, group_pointer, grouped) in enumerate(funding_groups(fields, pointer)):
        expected_entries[(*prefix, ordinal)] = (group, grouped)
        add_mentions(prefix, group, 'funding_entry', ordinal, group_pointer, grouped)

assert len(entries) == len(expected_entries) == 8699
assert len(funders) == len(expected_funders) == 8088
entry_ids = {entry['funding_entry_id']: entry for entry in entries}
funder_ids = {funder['funder_id']: funder for funder in funders}
assert len(entry_ids) == len(entries)
assert len(funder_ids) == len(funders)

for entry in entries:
    identity = (entry['member_id'], entry['declaration_id'], entry['register_id'], entry['funding_ordinal'])
    fields, grouped = expected_entries.pop(identity)
    values = {field['name']: field.get('value') for field in fields}
    for column, field in [('payer_name', 'PayerName'), ('ultimate_payer_name', 'UltimatePayerName'), ('payment_type', 'PaymentType'), ('funder_kind', 'DonorStatus'), ('company_number', 'DonorCompanyIdentifier'), ('is_ultimate_payer_different', 'IsUltimatePayerDifferent')]:
        assert entry[column] == values.get(field), (identity, column)
    donor = values.get('DonorName')
    if donor is None and grouped:
        donor = values.get('Name')
    assert entry['donor_name'] == donor
    amount = values.get('Value')
    if isinstance(amount, (int, Decimal)):
        assert Decimal(entry['amount']) == amount
    else:
        assert entry['amount'] == amount
    currency = next(((field.get('typeInfo') or {}).get('currencyCode') for field in fields if field['name'] == 'Value'), None)
    assert entry['currency'] == currency
    for role in ('donor', 'payer', 'ultimate_payer'):
        reference = entry[role + '_funder_id']
        expected_key = (*identity[:3], 'funding_entry', identity[3], role)
        assert (reference is not None) == (expected_key in expected_funders)
        if reference is not None:
            observation = funder_ids[reference]
            assert observation['role'] == role
            assert observation['funding_entry_id'] == entry['funding_entry_id']

for funder in funders:
    identity = (funder['member_id'], funder['declaration_id'], funder['register_id'], funder['source_scope'], funder['funding_ordinal'], funder['role'])
    expected = expected_funders.pop(identity)
    actual = (funder['name_raw'], funder['donor_kind'], funder['donor_company_number'], funder['source_pointer'])
    assert actual == expected, (identity, actual, expected)
    source = sources[(funder['member_id'], funder['declaration_id'])]
    for part in funder['source_pointer'].strip('/').split('/'):
        source = source[int(part)] if isinstance(source, list) else source[part]
    assert isinstance(source, list)
    assert all(isinstance(field, dict) and 'name' in field for field in source)
    assert (funder['funding_entry_id'] is None) == (funder['source_scope'] == 'declaration')
    if funder['funding_entry_id'] is not None:
        assert funder['funding_entry_id'] in entry_ids
    if funder['name_status'] == 'withheld':
        assert all(funder[column] is None for column in ('name_normalized', 'name_tokens', 'organisation_core', 'person_core'))

assert not expected_entries and not expected_funders
files = list(original.glob('*.parquet'))
assert len(files) == 655
for path in files:
    copied = run / 'raw/declarations' / path.name
    assert hashlib.sha256(path.read_bytes()).digest() == hashlib.sha256(copied.read_bytes()).digest(), path

print(json.dumps({'funding_entries_verified': len(entries), 'funder_observations_verified': len(funders), 'roles': dict(Counter(row['role'] for row in funders)), 'scopes': dict(Counter(row['source_scope'] for row in funders)), 'source_pointers_verified': len(funders), 'raw_partitions_unchanged': len(files)}, indent=2))
