    assert_eq!(group.funder_kind(), Some("Other"));
    assert_eq!(group.company_number(), Some("SC001234"));
    assert_eq!(group.amount(), Some("12345678901234567890.1234500"));
    assert_eq!(group.currency(), Some("GBP"));
}

