128	fn decode_source(source: Value, fetched_at: DateTime<Utc>) -> Result<DecodedDeclaration, ApiError> {
129	    let source_json = source.to_string();
130	    let source: Interest = serde_json::from_value(source)?;
131	    let (version_index, latest) = source
132	        .versions
133	        .into_iter()
134	        .enumerate()
135	        .max_by_key(|(_, version)| (version.register.published_date, version.register.id))
136	        .ok_or_else(|| ApiError::ResponseError("declaration has no published version".into()))?;
137	    let pointer = format!("/versions/{version_index}/fields");
138	    let fields = latest.fields.unwrap_or_default();
139	    let mut funding = Vec::new();
140	    let mut pointers = Vec::new();
141	    funding_entries(&fields, &pointer, &mut funding, &mut pointers)?;
142	    let declaration = CapturedDeclaration::new(
143	        DeclarationId::new(source.id)?,
144	        source
145	            .parent_interest_id
146	            .map(DeclarationId::new)
147	            .transpose()?,
148	        source.category.id,
149	        source.category.name,
150	        latest.register.id,
151	        latest.register.published_date,
152	        latest.registration_date,
153	        funding,
154	        fetched_at,
155	        source_json,
156	    )?;
157	    Ok(DecodedDeclaration {
158	        declaration,
159	        fields,
160	        source_pointer: pointer,
161	        funding_source_pointers: pointers,
162	    })
163	}
