165	fn has_funding_anchor(fields: &[SourceField]) -> bool {
166	    fields
167	        .iter()
168	        .any(|field| matches!(field.name.as_str(), "Value" | "PaymentType"))
169	}
170	
171	fn funding_entries(
172	    fields: &[SourceField],
173	    pointer: &str,
174	    entries: &mut Vec<CapturedFundingEntry>,
175	    pointers: &mut Vec<String>,
176	) -> Result<(), ApiError> {
177	    if has_funding_anchor(fields) {
178	        entries.push(parse_funding_entry(fields, false)?);
179	        pointers.push(pointer.to_owned());
180	    }
181	    for (field_index, field) in fields.iter().enumerate() {
182	        for (entry_index, nested) in field.values.iter().flatten().enumerate() {
183	            let pointer = format!("{pointer}/{field_index}/values/{entry_index}");
184	            if field.name == "Donors" {
185	                entries.push(parse_funding_entry(nested, true)?);
186	                pointers.push(pointer);
187	            } else {
188	                funding_entries(nested, &pointer, entries, pointers)?;
189	            }
190	        }
191	    }
192	    Ok(())
193	}
194	
195	fn parse_funding_entry(
196	    fields: &[SourceField],
197	    donor: bool,
198	) -> Result<CapturedFundingEntry, ApiError> {
199	    let values = fields
200	        .iter()
201	        .map(|field| (field.name.clone(), field.value.clone()))
202	        .collect();
203	    let funding: FundingFields = serde_json::from_value(Value::Object(values))?;
204	    let currency = fields
205	        .iter()
206	        .find(|field| field.name == "Value")
207	        .and_then(|field| field.type_info.as_ref())
208	        .and_then(|info| info.currency_code.clone());
209	    let donor_name = funding
210	        .donor_name
211	        .or(if donor { funding.name } else { None });
212	    Ok(CapturedFundingEntry::new(
213	        funding.ultimate_payer_name,
214	        donor_name,
215	        funding.payer_name,
216	        funding.value.map(Amount::into_text),
217	        currency,
218	        funding.payment_type,
219	        funding.donor_status,
220	        funding.donor_company_identifier,
221	        funding.is_ultimate_payer_different,
222	    ))
223	}
