   129	fn normalize(raw: &str) -> String {
   130	    raw.nfkc()
   131	        .flat_map(char::to_lowercase)
   132	        .collect::<String>()
   133	        .split_whitespace()
   134	        .collect::<Vec<_>>()
   135	        .join(" ")
   136	}
   137	
   138	fn tokens(name: &str) -> String {
   139	    let mut result = String::new();
   140	    for word in name.split_whitespace() {
   141	        let acronym = word.trim_matches(|c: char| !c.is_alphanumeric() && c != '.');
   142	        let dotted_acronym = acronym.contains('.')
   143	            && acronym.trim_end_matches('.').split('.').all(|part| {
   144	                let mut letters = part.chars();
   145	                letters.next().is_some_and(char::is_alphabetic) && letters.next().is_none()
   146	            });
   147	        for c in word.chars() {
   148	            match c {
   149	                '&' => result.push_str(" and "),
   150	                '\'' | '\u{2019}' | '\u{2018}' | '\u{02bc}' => {}
   151	                '.' if dotted_acronym => {}
   152	                c if c.is_alphanumeric() || is_combining_mark(c) => result.push(c),
   153	                _ => result.push(' '),
   154	            }
   155	        }
   156	        result.push(' ');
   157	    }
   158	    result.split_whitespace().collect::<Vec<_>>().join(" ")
   159	}
   160	
   161	fn organisation_core(name: &str) -> String {
   162	    const SUFFIXES: &[&[&str]] = &[
   163	        &["public", "limited", "company"],
   164	        &["community", "interest", "company"],
   165	        &["limited", "liability", "partnership"],
   166	        &["limited", "partnership"],
   167	        &["limited"],
   168	        &["ltd"],
   169	        &["plc"],
   170	        &["llp"],
   171	        &["lp"],
   172	        &["cic"],
   173	    ];
   174	    let mut words = name.split_whitespace().collect::<Vec<_>>();
   175	    if let Some(suffix) = SUFFIXES.iter().find(|suffix| words.ends_with(suffix)) {
   176	        words.truncate(words.len() - suffix.len());
   177	    }
   178	    words.join(" ")
   179	}
   180	
   181	fn person_core(name: &str) -> String {
   182	    const TITLES: &[&str] = &[
   183	        "mr",
   184	        "mrs",
   185	        "ms",
   186	        "miss",
   187	        "mx",
   188	        "dr",
   189	        "prof",
   190	        "professor",
   191	        "sir",
   192	        "dame",
   193	        "lord",
   194	        "lady",
   195	        "rev",
   196	        "reverend",
   197	        "rt",
   198	        "hon",
   199	    ];
   200	    name.split_whitespace()
   201	        .skip_while(|word| TITLES.contains(word))
   202	        .collect::<Vec<_>>()
   203	        .join(" ")
   204	}
   205	
   206	fn initials(name: &str, omit_connectives: bool) -> String {
   207	    const CONNECTIVES: &[&str] = &["a", "an", "and", "for", "in", "of", "on", "the", "to"];
   208	    name.split_whitespace()
   209	        .filter(|word| !omit_connectives || !CONNECTIVES.contains(word))
   210	        .filter_map(|word| word.chars().next())
   211	        .collect()
   212	}
   213	
   214	fn parentheses(raw: &str) -> (Vec<String>, bool) {
   215	    let mut result = Vec::new();
   216	    let mut depth = 0;
   217	    let mut start = 0;
   218	    let mut unbalanced = false;
   219	    for (index, c) in raw.char_indices() {
   220	        match c {
   221	            '(' => {
   222	                if depth == 0 {
   223	                    start = index + 1;
   224	                }
   225	                depth += 1;
   226	            }
   227	            ')' if depth > 0 => {
   228	                depth -= 1;
   229	                if depth == 0 {
   230	                    result.push(raw[start..index].to_owned());
   231	                }
   232	            }
   233	            ')' => unbalanced = true,
   234	            _ => {}
   235	        }
   236	    }
   237	    if depth > 0 {
   238	        result.push(raw[start..].to_owned());
   239	    }
   240	    (result, unbalanced || depth > 0)
   241	}
   242	
   243	fn explicit_acronym(raw: &str, parenthetical: &[String]) -> Option<(String, String)> {
   244	    let before = raw.split('(').next()?.trim();
   245	    for expansion in parenthetical {
   246	        for (candidate, full) in [(before, expansion.as_str()), (expansion.as_str(), before)] {
   247	            let letters = candidate
   248	                .chars()
   249	                .filter(|c| *c != '.' && !c.is_whitespace())
   250	                .collect::<String>();
   251	            if (2..=10).contains(&letters.chars().count())
   252	                && letters.chars().all(|c| c.is_ascii_uppercase())
   253	                && letters.to_lowercase() == initials(&tokens(&normalize(full)), true)
   254	            {
   255	                return Some((letters.to_lowercase(), normalize(full)));
   256	            }
   257	        }
   258	    }
   259	    None
   260	}
   261	
   262	fn alias_marker(candidate: &str, top_level_only: bool) -> Option<(usize, usize)> {
   263	    let lower = candidate.to_ascii_lowercase();
   264	    let mut found = None;
   265	    for marker in ["trading as", "t/a"] {
   266	        for (index, _) in lower.match_indices(marker) {
   267	            let boundary = (index == 0 || lower[..index].ends_with([' ', '(', ',']))
   268	                && lower[index + marker.len()..].starts_with(char::is_whitespace);
   269	            let depth = candidate[..index].chars().fold(0_i32, |depth, c| match c {
   270	                '(' => depth + 1,
   271	                ')' => depth - 1,
   272	                _ => depth,
   273	            });
   274	            if boundary
   275	                && (!top_level_only || depth == 0)
   276	                && found.is_none_or(|(previous, _)| index < previous)
   277	            {
   278	                found = Some((index, marker.len()));
   279	            }
   280	        }
   281	    }
   282	    found
   283	}
   284	
   285	fn aliases(raw: &str, parenthetical: &[String]) -> Vec<String> {
   286	    let mut result = Vec::new();
   287	    for (candidate, top_level_only) in parenthetical
   288	        .iter()
   289	        .map(|name| (name.as_str(), false))
   290	        .chain(std::iter::once((raw, true)))
   291	    {
   292	        if let Some((index, length)) = alias_marker(candidate, top_level_only) {
   293	            let alias = candidate[index + length..].trim().to_owned();
   294	            if !alias.is_empty() && !result.contains(&alias) {
   295	                result.push(alias);
   296	            }
   297	        }
   298	    }
   299	    result
   300	}
   301	
   302	fn primary_name(raw: &str) -> String {
   303	    let mut result = String::new();
   304	    let mut depth = 0;
   305	    let mut start = 0;
   306	    let mut keep_from = 0;
   307	    for (index, c) in raw.char_indices() {
   308	        match c {
   309	            '(' => {
   310	                if depth == 0 {
   311	                    start = index;
   312	                }
   313	                depth += 1;
   314	            }
   315	            ')' if depth > 0 => {
   316	                depth -= 1;
   317	                if depth == 0 && alias_marker(&raw[start + 1..index], false).is_some() {
   318	                    result.push_str(&raw[keep_from..start]);
   319	                    result.push(' ');
   320	                    keep_from = index + 1;
   321	                }
   322	            }
   323	            _ => {}
   324	        }
   325	    }
   326	    result.push_str(&raw[keep_from..]);
   327	    if let Some((index, _)) = alias_marker(&result, true) {
   328	        result.truncate(index);
   329	    }
   330	    result.trim().trim_end_matches(',').trim().to_owned()
   331	}
