   129	fn normalize(raw: &str) -> String {
   130	    raw.nfkc()
   131	        .flat_map(char::to_lowercase)
   132	        .collect::<String>()
   133	        .split_whitespace()
   134	        .collect::<Vec<_>>()
   135	        .join(" ")
   136	}
   137	
   138	fn tokens(name: &str) -> String {
   139	    let mut result = String::new();
   140	    for word in name.split_whitespace() {
   141	        let acronym = word.trim_matches(|c: char| !c.is_alphanumeric() && c != '.');
   142	        let dotted_acronym = acronym.contains('.')
   143	            && acronym.trim_end_matches('.').split('.').all(|part| {
   144	                let mut letters = part.chars();
   145	                letters.next().is_some_and(char::is_alphabetic) && letters.next().is_none()
   146	            });
   147	        for c in word.chars() {
   148	            match c {
   149	                '&' => result.push_str(" and "),
   150	                '\'' | '\u{2019}' | '\u{2018}' | '\u{02bc}' => {}
   151	                '.' if dotted_acronym => {}
   152	                c if c.is_alphanumeric() || is_combining_mark(c) => result.push(c),
   153	                _ => result.push(' '),
   154	            }
   155	        }
   156	        result.push(' ');
   157	    }
   158	    result.split_whitespace().collect::<Vec<_>>().join(" ")
   159	}
   160	
   161	fn organisation_core(name: &str) -> String {
   162	    const SUFFIXES: &[&[&str]] = &[
   163	        &["public", "limited", "company"],
   164	        &["community", "interest", "company"],
   165	        &["limited", "liability", "partnership"],
   166	        &["limited", "partnership"],
   167	        &["limited"],
   168	        &["ltd"],
   169	        &["plc"],
   170	        &["llp"],
   171	        &["lp"],
   172	        &["cic"],
   173	    ];
   174	    let mut words = name.split_whitespace().collect::<Vec<_>>();
   175	    if let Some(suffix) = SUFFIXES.iter().find(|suffix| words.ends_with(suffix)) {
   176	        words.truncate(words.len() - suffix.len());
   177	    }
   178	    words.join(" ")
   179	}
