   181	fn person_core(name: &str) -> String {
   182	    const TITLES: &[&str] = &[
   183	        "mr",
   184	        "mrs",
   185	        "ms",
   186	        "miss",
   187	        "mx",
   188	        "dr",
   189	        "prof",
   190	        "professor",
