   192	        "dame",
   193	        "lord",
   194	        "lady",
   195	        "rev",
   196	        "reverend",
   197	        "rt",
   198	        "hon",
   199	    ];
   200	    name.split_whitespace()
   201	        .skip_while(|word| TITLES.contains(word))
   202	        .collect::<Vec<_>>()
   203	        .join(" ")
   204	}
