   206	fn initials(name: &str, omit_connectives: bool) -> String {
   207	    const CONNECTIVES: &[&str] = &["a", "an", "and", "for", "in", "of", "on", "the", "to"];
   208	    name.split_whitespace()
   209	        .filter(|word| !omit_connectives || !CONNECTIVES.contains(word))
   210	        .filter_map(|word| word.chars().next())
   211	        .collect()
   212	}
