   131	    let (version_index, latest) = source
   132	        .versions
   133	        .into_iter()
   134	        .enumerate()
   135	        .max_by_key(|(_, version)| (version.register.published_date, version.register.id))
   136	        .ok_or_else(|| ApiError::ResponseError("declaration has no published version".into()))?;
   137	    let pointer = format!("/versions/{version_index}/fields");
   138	    let fields = latest.fields.unwrap_or_default();
