    let reader = ParquetRecordBatchReaderBuilder::try_new(File::open(&raw)?)?.build()?;
    let batches = reader.collect::<Result<Vec<_>, _>>()?;
    let order = (0..batches[0].num_columns()).rev().collect::<Vec<_>>();
